1	// andes-sim -- multi-engine driver for the Andes simulators (QEMU, Verilator,
2	// and future backends). One C++20 binary that selects a model (fast / accurate
3	// / hybrid), resolves engines at runtime, and either passes through to a single
4	// engine or orchestrates a hybrid round-trip.
5	//
6	// This file owns argument dispatch only: parse the CLI, route to a command.
7	// Each subcommand below resolves to its handler as its feature lands (F1-F13);
8	// until then it stubs out, keeping the command surface stable.
9	#include <cstdio>
10	#include <exception>
11	#include <string>
12	#include <string_view>
13	
14	#include "cli.hpp"
15	#include "repo_root.hpp"
16	
17	namespace andes_sim {
18	int cmd_list(const Cli& cli);
19	int cmd_doctor(const Cli& cli);
20	int cmd_build(const Cli& cli);
21	int cmd_run(const Cli& cli);
22	}  // namespace andes_sim
23	
24	namespace {
25	
26	using andes_sim::Cli;
27	
28	struct Subcommand {
29	  std::string_view name;
30	  std::string_view brief;
31	};
32	
33	// The full command surface. Names are fixed from F0 so usage, dispatch, and
34	// tests are stable; handlers arrive feature by feature.
35	constexpr Subcommand kSubcommands[] = {
36	    {"build", "build artifacts (qemu, vsim, plugin, simpoint, fixtures, driver)"},
37	    {"run", "run one simulation (--model fast|accurate|hybrid)"},
38	    {"test", "run the end-to-end suite"},
39	    {"list", "list fixtures|models|engines"},
40	    {"doctor", "check environment health"},
41	    {"profile", "profile a workload into a basic-block vector"},
42	    {"cluster", "cluster a BBV into SimPoint phases"},
43	    {"archive", "snapshot a drained state into a replayable dir"},
44	    {"replay", "replay a snapshot"},
45	    {"estimate", "whole-program cycle estimate (run --model hybrid --trigger simpoint)"},
46	};
47	
48	const Subcommand* find(std::string_view name) {
49	  for (const Subcommand& s : kSubcommands)
50	    if (s.name == name) return &s;
51	  return nullptr;
52	}
53	
54	void print_usage(std::FILE* out) {
55	  std::fputs("usage: andes-sim <cmd> [args...]\n\n", out);
56	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + Verilator).\n\n",
57	             out);
58	  std::fputs("commands:\n", out);
59	  for (const Subcommand& s : kSubcommands)
60	    std::fprintf(out, "  %-9.*s  %.*s\n", static_cast<int>(s.name.size()),
61	                 s.name.data(), static_cast<int>(s.brief.size()), s.brief.data());
62	}
63	
64	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
65	  std::fprintf(out, "usage: andes-sim %.*s [args...]\n\n",
66	               static_cast<int>(sc.name.size()), sc.name.data());
67	  std::fprintf(out, "%.*s\n", static_cast<int>(sc.brief.size()), sc.brief.data());
68	  if (sc.name == "run") {
69	    std::fputs(
70	        "\nselection:\n"
71	        "  --model fast|accurate|hybrid       which composition to run\n"
72	        "  --engine <id>                      pick a specific engine "
73	        "(e.g. verilator:ax45mpv_premium)\n"
74	        "  --trigger csr|pc|icount|simpoint   ROI delimiter (hybrid only)\n"
75	        "  -- <args...>                       forward everything after -- "
76	        "verbatim to the engine\n",
77	        out);
78	  } else if (sc.name == "list") {
79	    std::fputs("\ntargets: fixtures | models | engines\n", out);
80	  }
81	}
82	
83	}  // namespace
84	
85	int main(int argc, char** argv) {
86	  using namespace andes_sim;
87	
88	  Cli cli = parse_cli(argc, argv);
89	  if (!cli.error.empty()) {
90	    std::fprintf(stderr, "andes-sim: %s\n", cli.error.c_str());
91	    return 2;
92	  }
93	
94	  if (cli.subcommand.empty()) {  // no command, or top-level -h
95	    if (cli.help) {
96	      print_usage(stdout);
97	      return 0;
98	    }
99	    print_usage(stderr);
100	    return 2;
101	  }
102	
103	  const Subcommand* sc = find(cli.subcommand);
104	  if (!sc) {
105	    std::fprintf(stderr, "andes-sim: unknown command '%s'\n\n",
106	                 cli.subcommand.c_str());
107	    print_usage(stderr);
108	    return 2;
109	  }
110	
111	  if (cli.help) {
112	    print_subcommand_help(*sc, stdout);
113	    return 0;
114	  }
115	
116	  if (cli.subcommand == "list") return cmd_list(cli);
117	  if (cli.subcommand == "doctor") return cmd_doctor(cli);
118	  if (cli.subcommand == "build") return cmd_build(cli);
119	  if (cli.subcommand == "run") return cmd_run(cli);
120	
121	  // Remaining subcommands stub out until their feature lands. Resolve the repo
122	  // root so the discovery path stays live and observable.
123	  std::string root;
124	  try {
125	    root = repo_root().string();
126	  } catch (const std::exception& e) {
127	    root = std::string("<unknown: ") + e.what() + ">";
128	  }
129	  std::fprintf(stderr, "andes-sim %s: not yet implemented (repo root: %s)\n",
130	               cli.subcommand.c_str(), root.c_str());
131	  return 3;
132	}
