28	std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
29	  std::ifstream f(p);
30	  std::vector<std::string> lines;
31	  ok = static_cast<bool>(f);
32	  if (!ok) return lines;
33	  std::string line;
34	  while (std::getline(f, line)) lines.push_back(line);
35	  return lines;
36	}
37	
38	// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
39	// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
40	// `var` and `body` (the text after `=`, continuation backslash included).
41	bool parse_assignment(const std::string& line, std::string& var,
42	                      std::string& body) {
43	  const size_t n = line.size();
44	  if (n == 0) return false;
45	  char c0 = line[0];
46	  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
47	  size_t p = 0;
48	  while (p < n) {
49	    char c = line[p];
50	    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
51	    else break;
52	  }
53	  var = line.substr(0, p);
54	  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
55	  if (p < n && line[p] == ':') ++p;                          // :?
56	  if (p >= n || line[p] != '=') return false;                // =
57	  ++p;
58	  body = line.substr(p);
59	  return true;
60	}
61	
62	struct Fixture {
63	  std::string name;
64	  std::string family;
65	};
66	
67	// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
68	// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
69	std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
70	  static const std::pair<std::string, std::string> interesting[] = {
71	      {"RT_FIXTURES", "asm"},
72	      {"RT_C_FIXTURES", "c"},
73	      {"RT_C_V_FIXTURES", "c+rvv"},
74	      {"PROBE_V_FIXTURES", "probe"},
75	  };
76	  std::vector<Fixture> rows;
77	  std::set<std::string> seen;
78	
79	  for (size_t k = 0; k < lines.size(); ++k) {
80	    std::string var, body;
81	    if (!parse_assignment(lines[k], var, body)) continue;
82	    std::string family;
83	    for (const auto& it : interesting)
84	      if (it.first == var) { family = it.second; break; }
85	    if (family.empty()) continue;
86	
87	    // Splice continuation lines: a trailing backslash + newline becomes a space.
88	    size_t li = k;
89	    while (!body.empty() && body.back() == '\\') {
90	      body.pop_back();
91	      body.push_back(' ');
92	      if (++li < lines.size()) body += lines[li];
93	      else break;
94	    }
95	
96	    std::istringstream iss(body);
97	    std::string name;
98	    while (iss >> name)
99	      if (seen.insert(name).second) rows.push_back({name, family});
100	  }
101	
102	  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
103	  if (seen.insert("handoff_roundtrip").second)
104	    rows.push_back({"handoff_roundtrip", "asm"});
105	
106	  return rows;
107	}
108	
109	int list_fixtures() {
110	  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
111	  bool ok;
112	  std::vector<std::string> lines = read_lines(mk, ok);
113	  if (!ok) {
114	    std::fprintf(stderr, "andes-sim: missing %s\n", mk.c_str());
115	    return 2;
116	  }
117	  std::vector<Fixture> rows = parse_fixtures(lines);
118	
119	  size_t width = 0;
120	  for (const Fixture& r : rows) width = std::max(width, r.name.size());
121	
122	  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
123	  for (const Fixture& r : rows)
124	    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
125	  return 0;
126	}
