128	int list_models() {
129	  size_t wn = 5, we = 7;  // header widths: MODEL, ENGINES
130	  for (const Model& m : kModels) {
131	    wn = std::max(wn, m.name.size());
132	    we = std::max(we, m.engines.size());
133	  }
134	  std::printf("%s  %s  NOTES\n", ljust("MODEL", wn).c_str(),
135	              ljust("ENGINES", we).c_str());
136	  for (const Model& m : kModels)
137	    std::printf("%s  %s  %s\n", ljust(std::string(m.name), wn).c_str(),
138	                ljust(std::string(m.engines), we).c_str(),
139	                std::string(m.notes).c_str());
140	  return 0;
141	}
