1	// `andes-sim build [--what TARGET] [--dry-run]`.
2	//
3	// A thin delegator: each target maps to an ordered list of subprocess steps
4	// that call the repo's existing build scripts / Makefiles (setup.sh,
5	// scripts/build_*.sh, make). No build logic is duplicated here -- this is a port
6	// of hsim's cmd_build. `--dry-run` prints the shlex-joined commands (byte-exact
7	// with the golden); a real run banners each step and inherits its stdio so the
8	// user watches the build live. Targets match the golden's six; `--what driver`
9	// (building this C++ driver) is an F14 addition.
10	#include <cstdio>
11	#include <string>
12	#include <vector>
13	
14	#include "cli.hpp"
15	#include "process.hpp"
16	#include "repo_root.hpp"
17	
18	namespace andes_sim {
19	namespace {
20	
21	// POSIX shell-quote one token (mirrors Python shlex.quote): empty -> ''; a token
22	// of only the safe set passes through unquoted; otherwise wrap in single quotes,
23	// rendering each embedded ' as the '"'"' splice.
24	std::string shlex_quote(const std::string& s) {
25	  if (s.empty()) return "''";
26	  auto safe = [](char c) {
27	    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
28	           (c >= '0' && c <= '9') || c == '_' || c == '@' || c == '%' ||
29	           c == '+' || c == '=' || c == ':' || c == ',' || c == '.' ||
30	           c == '/' || c == '-';
31	  };
32	  bool all_safe = true;
33	  for (char c : s)
34	    if (!safe(c)) { all_safe = false; break; }
35	  if (all_safe) return s;
36	  std::string q = "'";
37	  for (char c : s) q += (c == '\'') ? "'\"'\"'" : std::string(1, c);
38	  q += "'";
39	  return q;
40	}
41	
42	std::string shlex_join(const std::vector<std::string>& argv) {
43	  std::string line;
44	  for (size_t i = 0; i < argv.size(); ++i) {
45	    if (i) line += ' ';
46	    line += shlex_quote(argv[i]);
47	  }
48	  return line;
49	}
50	
51	using Step = std::vector<std::string>;
52	
53	// Map a --what target to its ordered steps (mirrors hsim's _build_steps).
54	// Returns false if the target is unknown. `root` is the absolute repo root, used
55	// for the plugin's QEMU_ROOT: it must be absolute because `make -C qemu_plugin`
56	// chdirs first, so a relative path (the old ./QEMU) would resolve under
57	// qemu_plugin/ and miss the headers -- setup.sh:115 passes an absolute path too.
58	bool build_steps(const std::string& what, const std::string& root,
59	                 std::vector<Step>& out) {
60	  const Step qemu = {"bash", "scripts/build_qemu.sh"};
61	  const Step vsim = {"bash", "scripts/build_vsim.sh"};
62	  const Step plugin = {"make", "-C", "qemu_plugin", "QEMU_ROOT=" + root + "/QEMU"};
63	  const Step simpoint = {"bash", "scripts/build_simpoint.sh"};
64	  const Step fixtures = {"make", "-C", "tests/fixtures"};
65	  const Step setup = {"bash", "setup.sh"};
66	  if (what == "all") { out = {setup, fixtures}; return true; }
67	  if (what == "qemu") { out = {qemu}; return true; }
68	  if (what == "vsim") { out = {vsim}; return true; }
69	  if (what == "plugin") { out = {plugin}; return true; }
70	  if (what == "simpoint") { out = {simpoint}; return true; }
71	  if (what == "fixtures") { out = {fixtures}; return true; }
