79	  const std::string root = repo_root().string();
80	  std::vector<Step> steps;
81	  if (!build_steps(what, root, steps)) {
82	    std::fprintf(stderr, "andes-sim: unknown build target: %s\n", what.c_str());
83	    return 2;
84	  }
85	
86	  for (const Step& argv : steps) {
87	    const std::string line = shlex_join(argv);
88	    if (cli.dry_run) {
89	      std::printf("%s\n", line.c_str());
90	      continue;
91	    }
92	    std::printf("[andes-sim] %s\n", line.c_str());
93	    std::fflush(stdout);  // banner before the child writes to the shared stdout
94	    int rc = run_inherit(argv, root);
95	    if (rc != 0) {
96	      std::fprintf(stderr, "andes-sim: build step failed (rc=%d): %s\n", rc,
97	                   line.c_str());
