129	// First PATH directory holding an executable non-directory named `tool`, joined
130	// the way shutil.which reports it (dir + '/' + tool). "" if not found.
131	std::string which(const std::string& tool) {
132	  const char* path = std::getenv("PATH");
133	  if (!path) return "";
134	  const std::string p(path);
135	  for (size_t i = 0; i <= p.size();) {
136	    size_t j = p.find(':', i);
137	    if (j == std::string::npos) j = p.size();
138	    std::string dir = p.substr(i, j - i);
139	    i = j + 1;
140	    if (dir.empty()) continue;
141	    std::string cand = dir.back() == '/' ? dir + tool : dir + "/" + tool;
142	    std::error_code ec;
143	    if (::access(cand.c_str(), X_OK) == 0 && !fs::is_directory(cand, ec))
144	      return cand;
145	  }
146	  return "";
147	}
