149	// Match `^\s*(?:export\s+)?HYBRID_TOOLCHAIN\s*=\s*(.+?)\s*$`; on match set `out`
150	// to the value with surrounding whitespace, then double, then single quotes
151	// stripped (mirrors hsim._read_hybrid_toolchain).
152	bool parse_toolchain_line(const std::string& line, std::string& out) {
153	  size_t i = 0, n = line.size();
154	  auto skip_ws = [&] {
155	    while (i < n && std::isspace(static_cast<unsigned char>(line[i]))) ++i;
156	  };
157	  skip_ws();
158	  const std::string kw = "export";
159	  if (line.compare(i, kw.size(), kw) == 0 && i + kw.size() < n &&
160	      std::isspace(static_cast<unsigned char>(line[i + kw.size()]))) {
161	    i += kw.size();
162	    skip_ws();
163	  }
164	  const std::string key = "HYBRID_TOOLCHAIN";
165	  if (line.compare(i, key.size(), key) != 0) return false;
166	  i += key.size();
167	  skip_ws();
168	  if (i >= n || line[i] != '=') return false;
169	  std::string rest = line.substr(i + 1);  // everything after '='
170	  if (rest.empty()) return false;         // regex (.+?) needs >= 1 char
171	  size_t b = 0, e = rest.size();
172	  while (b < e && std::isspace(static_cast<unsigned char>(rest[b]))) ++b;
173	  while (e > b && std::isspace(static_cast<unsigned char>(rest[e - 1]))) --e;
174	  std::string val = strip_char(rest.substr(b, e - b), '"');
175	  out = strip_char(val, '\'');
176	  return true;
177	}
178	
179	// HYBRID_TOOLCHAIN: env first (non-empty wins), else the first matching
180	// assignment in config.env. "" if neither yields a value.
181	std::string read_hybrid_toolchain() {
182	  const char* env = std::getenv("HYBRID_TOOLCHAIN");
183	  if (env && *env) return env;
184	  std::ifstream f(repo_root() / "config.env");
185	  if (!f) return "";
186	  std::string line, val;
187	  while (std::getline(f, line))
188	    if (parse_toolchain_line(line, val)) return val;
189	  return "";
190	}
