192	std::vector<Row> doctor_toolchain() {
193	  struct T {
194	    const char* tool;
195	    const char* hint;
196	    bool warn_only;  // a missing podman warns; ninja/make fail
197	  };
198	  const T tools[] = {
199	      {"ninja", "needed by ./hsim build of QEMU", false},
200	      {"make", "needed by ./hsim build of fixtures + simpoint", false},
201	      {"podman", "needed by ./hsim build of vsim (or docker shim)", true},
202	  };
203	  std::vector<Row> rows;
204	  for (const T& t : tools) {
205	    std::string found = which(t.tool);
206	    if (!found.empty())
207	      rows.push_back({t.tool, "PASS", found});
208	    else
209	      rows.push_back({t.tool, t.warn_only ? "WARN" : "FAIL",
210	                      std::string("not on PATH -- ") + t.hint});
211	  }
212	
213	  std::string tc = read_hybrid_toolchain();
214	  if (tc.empty()) {
215	    rows.push_back({"HYBRID_TOOLCHAIN", "WARN",
216	                    "not set -- needed for fixture build (see config.env)"});
217	  } else {
218	    fs::path gcc = fs::path(tc) / "bin" / "riscv64-unknown-elf-gcc";
219	    if (fs::is_regular_file(gcc))
220	      rows.push_back({"riscv64-unknown-elf-gcc", "PASS", gcc.string()});
221	    else
222	      rows.push_back({"riscv64-unknown-elf-gcc", "FAIL",
223	                      "missing " + gcc.string() +
224	                          " -- check HYBRID_TOOLCHAIN=" + tc});
225	  }
226	  return rows;
227	}
