231	constexpr long kDefaultJobs = 8;
232	
233	std::vector<Row> doctor_runtime() {
234	  std::vector<Row> rows;
235	  long nproc = sysconf(_SC_NPROCESSORS_ONLN);
236	  if (nproc < 1) nproc = 1;
237	  rows.push_back({"nproc", "INFO", std::to_string(nproc)});
238	
239	  std::error_code ec;
240	  if (fs::is_directory("/dev/shm", ec)) {
241	    struct statvfs vfs{};
242	    unsigned long long free_gb = 0;
243	    if (statvfs("/dev/shm", &vfs) == 0)
244	      free_gb = static_cast<unsigned long long>(vfs.f_bavail) * vfs.f_frsize /
245	                (1024ULL * 1024 * 1024);
246	    rows.push_back({"/dev/shm free", free_gb >= 4 ? "PASS" : "WARN",
247	                    std::to_string(free_gb) + " GB"});
248	  } else {
249	    rows.push_back({"/dev/shm", "WARN",
250	                    "not present -- e2e fixtures will fall back to $TMPDIR"});
251	  }
252	
253	  long suggested = std::min(nproc, kDefaultJobs);
254	  rows.push_back({"JOBS suggestion", "INFO",
255	                  std::to_string(suggested) + " (default cap = " +
256	                      std::to_string(kDefaultJobs) + ")"});
257	  return rows;
258	}
