261	
262	// Reflects `list engines` from the same F2 discovery, in doctor's row idiom.
263	// INFO-tagged and printed after Summary, so it never moves the summary counts
264	// or the exit code. Discovery warnings surface as WARN rows here.
265	void print_engines_section() {
266	  Discovery disc = discover_engines();
267	  size_t w = 0;
268	  for (const EngineDescriptor& e : disc.engines) w = std::max(w, e.id.size());
269	
270	  std::printf("\nengines:\n");
271	  for (const EngineDescriptor& e : disc.engines)
272	    std::printf("  [INFO] %s  kind=%s vlen=%s triggers=%s\n",
273	                ljust(e.id, w).c_str(), e.kind.c_str(), vlen_str(e.vlen).c_str(),
274	                join(e.triggers).c_str());
275	  for (const std::string& warn : disc.warnings)
276	    std::printf("  [WARN] %s\n", warn.c_str());
