286	int cmd_doctor(const Cli&) {
287	  std::vector<Section> sections = {
288	      {"artifacts", doctor_artifacts()},
289	      {"submodules", doctor_submodules()},
290	      {"toolchain", doctor_toolchain()},
291	      {"runtime", doctor_runtime()},
292	  };
293	
294	  size_t name_width = 0;
295	  for (const Section& s : sections)
296	    for (const Row& r : s.rows) name_width = std::max(name_width, r.name.size());
297	
298	  int passes = 0, fails = 0, warns = 0;
299	  for (const Section& s : sections) {
300	    std::printf("%s:\n", s.title);
301	    for (const Row& r : s.rows) {
302	      if (r.status == "PASS") ++passes;
303	      else if (r.status == "FAIL") ++fails;
304	      else if (r.status == "WARN") ++warns;
305	      std::printf("  [%-4s] %s  %s\n", r.status.c_str(),
306	                  ljust(r.name, name_width).c_str(), r.detail.c_str());
307	    }
308	    std::printf("\n");
309	  }
310	  std::printf("Summary: %d PASS, %d FAIL, %d WARN\n", passes, fails, warns);
311	
312	  print_engines_section();
313	  return fails > 0 ? 1 : 0;
314	}
