153	Discovery discover_engines() {
154	  Discovery out;
155	  std::set<std::string> seen;
156	
157	  EngineDescriptor qemu = builtin_qemu();
158	  seen.insert(qemu.id);
159	  out.engines.push_back(std::move(qemu));
160	
161	  if (const char* env = std::getenv("ANDES_SIM_ENGINES_DIR"); env && *env) {
162	    std::stringstream ss(env);
163	    std::string dir;
164	    while (std::getline(ss, dir, ':'))
165	      if (!dir.empty()) scan_dir(dir, /*prefix=*/"", out, seen);
166	  } else {
167	    scan_dir(repo_root() / "verilator" / "build", /*prefix=*/"sim_", out, seen);
168	  }
169	  return out;
170	}
