29	Cli parse_cli(const std::vector<std::string>& args) {
30	  Cli c;
31	  if (args.empty()) return c;  // no subcommand; caller prints usage
32	
33	  // First token is the subcommand, unless it is a top-level help request.
34	  if (args[0] == "-h" || args[0] == "--help") {
35	    c.help = true;
36	    return c;
37	  }
38	  c.subcommand = args[0];
39	
40	  for (size_t i = 1; i < args.size(); ++i) {
41	    const std::string& a = args[i];
42	
43	    if (a == "--") {  // the passthrough boundary: rest is verbatim
44	      c.has_passthrough = true;
45	      for (size_t j = i + 1; j < args.size(); ++j) c.passthrough.push_back(args[j]);
46	      break;
47	    }
48	    if (a == "-h" || a == "--help") {
49	      c.help = true;
50	      continue;
51	    }
52	    if (a == "--dry-run") {
53	      c.dry_run = true;
54	      continue;
55	    }
56	
57	    const struct {
58	      const char* flag;
59	      std::string* out;
60	    } opts[] = {{"--model", &c.model},
61	                {"--engine", &c.engine},
62	                {"--trigger", &c.trigger},
63	                {"--what", &c.what},
64	                {"--pc-start", &c.pc_start},
65	                {"--pc-end", &c.pc_end},
66	                {"--qemu-icount", &c.qemu_icount},
67	                {"--vsim-icount", &c.vsim_icount},
68	                {"--mmap-size", &c.mmap_size},
69	                {"--vsim-warmup-icount", &c.vsim_warmup_icount},
70	                {"--kanata", &c.kanata},
71	                {"--objdump", &c.objdump}};
72	    bool consumed = false;
73	    for (const auto& o : opts) {
74	      int r = match_opt(args, i, o.flag, *o.out);
75	      if (r < 0) { c.error = std::string("missing value for ") + o.flag; return c; }
76	      if (r > 0) { consumed = true; break; }
77	    }
78	    if (consumed) continue;
79	
80	    if (a.size() > 1 && a[0] == '-') {
81	      c.error = "unknown option: " + a;
82	      return c;
83	    }
84	    c.positional.push_back(a);
85	  }
86	
87	  return c;
88	}
89	
90	Cli parse_cli(int argc, char** argv) {
91	  std::vector<std::string> args;
92	  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
93	  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
94	  return parse_cli(args);
95	}
